# Generated by manage.py generate_test_cases.
import json

from bs4 import BeautifulSoup
from django.contrib.auth.models import Group
from django.http import HttpResponse
from django.urls import reverse

from bloomerp.models.workspaces.workspace import Workspace
from bloomerp.services.preference_services import PreferenceManager
from bloomerp.tests.base import (
    BloomerpViewTestCase,
    ExpectedResult,
    RequestScenario,
)


class TestMyWorkspacesView(BloomerpViewTestCase):
    """Tests class `MyWorkspacesView` from `bloomerp/views/workspaces/my_workspaces.py`."""

    view_name = "my_workspaces"

    def extendedSetup(self) -> None:
        """Create owned, directly shared, group-shared, and private workspaces."""
        self.owned = Workspace.objects.create(user=self.normal_user, name="My workspace")
        self.direct = Workspace.objects.create(user=self.admin_user, name="Direct share")
        self.direct.shared_with_users.add(self.normal_user)
        PreferenceManager(self.normal_user).select(self.direct)
        self.direct.name = "Direct share renamed"
        self.direct.save(update_fields=["name"])

        group = Group.objects.create(name="Workspace viewers")
        self.normal_user.groups.add(group)
        self.group_shared = Workspace.objects.create(user=self.admin_user, name="Group share")
        self.group_shared.shared_with_groups.add(group)
        self.private = Workspace.objects.create(user=self.admin_user, name="Private workspace")

    def dataview_request(self, response: HttpResponse) -> tuple[str, dict[str, str]]:
        """Read the clean URL and shared context of the My Workspaces loader."""
        loader = BeautifulSoup(response.content, "html.parser").select_one(
            'div[hx-headers][hx-trigger="load"]'
        )
        self.assertIsNotNone(loader)
        self.assertNotIn("_dataview_token", loader["hx-get"])
        return loader["hx-get"], {"HX-Request": "true", **json.loads(loader["hx-headers"])}

    def shows_available_workspaces(self, response: HttpResponse) -> bool:
        """Check the toolbar, live names, open links, search, and revoked access."""
        url, headers = self.dataview_request(response)
        dataview = self.client.get(url, headers=headers)
        self.assertContains(dataview, 'data-view-type="card"')
        markup = BeautifulSoup(dataview.content, "html.parser")
        create = markup.select_one('[data-data-view-button="add"] button[hx-get]')
        self.assertIsNotNone(create)
        navigation = self.client.get(create["hx-get"], headers=headers)
        self.assertEqual(navigation.status_code, 200)
        location = json.loads(navigation.headers["HX-Location"])
        self.assertEqual(location["path"], reverse("workspaces_add"))
        self.assertEqual(location["target"], "#main-content")
        form = self.client.get(
            location["path"], headers={"HX-Request": "true", "HX-Target": "main-content"},
        )
        self.assertContains(form, 'name="name"')

        cards = markup.select("[data-dataview-record]")
        self.assertCountEqual(
            [card["data-object-string"] for card in cards],
            [self.owned.name, self.direct.name, self.group_shared.name],
        )
        for card in cards:
            actions = card.select("[data-object-action-id]")
            self.assertEqual([action["data-object-action-id"] for action in actions], ["open-workspace"])
            self.assertEqual(actions[0]["hx-get"], card["data-detail-url"])
        workspace_url = self.direct.get_absolute_url()
        self.assertContains(dataview, f'data-detail-url="{workspace_url}"')
        opened = self.client.get(workspace_url, headers={"HX-Request": "true", "HX-Target": "main-content"})
        self.assertEqual(opened.status_code, 200)

        search = self.client.get(url, {"q": "Direct"}, headers=headers)
        self.assertContains(search, self.direct.name)
        self.assertNotContains(search, self.group_shared.name)

        self.direct.shared_with_users.remove(self.normal_user)
        refreshed = self.client.get(url, headers=headers)
        self.assertNotContains(refreshed, self.direct.name)
        self.assertContains(refreshed, self.group_shared.name)
        return True

    def keeps_admin_list_scoped(self, response: HttpResponse) -> bool:
        """Keep unshared workspaces outside the list even for a superuser."""
        url, headers = self.dataview_request(response)
        dataview = self.client.get(url, headers=headers)
        self.assertContains(dataview, self.private.name)
        self.assertNotContains(dataview, self.owned.name)
        return True

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Cover the card list for an ordinary user and a superuser."""
        return [
            RequestScenario(
                name="Owned and shared workspaces appear as cards with live access",
                user=self.normal_user,
                expected=ExpectedResult(response_validators=self.shows_available_workspaces),
            ),
            RequestScenario(
                name="The superuser sees their own workspaces",
                user=self.admin_user,
                expected=ExpectedResult(response_validators=self.keeps_admin_list_scoped),
            ),
        ]
